import numpy as np
from scipy.sparse.linalg import eigs
from reference import Task

task = Task()
seeds = list(range(1, 21))
problems = [task.generate_problem(n=300, random_seed=s) for s in seeds]

def sim_check(ev, evec, re, rv, tol=1e-6):
    # sort both by abs eigenvalue
    idx = np.argsort(-np.abs(ev))
    ridx = np.argsort(-np.abs(re))
    evs = ev[idx]; revs = re[ridx]
    if not np.allclose(np.abs(evs), np.abs(revs), rtol=1e-5, atol=1e-8):
        return False, "eval_mod", np.max(np.abs(np.abs(evs)-np.abs(revs)))
    # vector alignment (phase invariant)
    worst = 1.0
    for i in range(len(evs)):
        a = evec[:, idx[i]]
        b = rv[:, ridx[i]]
        sim = np.abs(np.vdot(b, a)) / (np.linalg.norm(a)*np.linalg.norm(b))
        worst = min(worst, sim)
        if sim < 1 - tol:
            return False, "vec", sim
    return True, "ok", worst

def run(A, k, ncv, tol=0, maxiter=None):
    n = A.shape[0]
    v0 = np.ones(n, dtype=A.dtype)
    return eigs(A, k=k, v0=v0, maxiter=maxiter or n*200, ncv=ncv, tol=tol)

for ncv in (12, 15, 16, 18, 20, 24, 30, 40):
    ok = 0
    worsts = []
    for p in problems:
        A = p["matrix"]
        re, rv = run(A, 5, 20)
        try:
            ev, evec = run(A, 5, ncv)
        except Exception as e:
            worsts.append(("fail", str(e)[:60]))
            continue
        good, kind, metric = sim_check(ev, evec, re, rv)
        if good:
            ok += 1
        else:
            worsts.append((kind, metric))
    print(f"ncv={ncv} ok={ok}/{len(problems)} fails={worsts[:3]}")
EOF"}

