#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>
#include <math.h>

/* ARPACK dnaupd reverse communication, matching scipy's dnaupd_wrap calling convention
   as closely as we can infer. We'll instead call through a function pointer obtained
   by dlsym from the already-loaded _arpacklib module... but the symbols are C ARNAUD_*.

   Safer approach: accept the Python dnaupd_wrap callable and only accelerate the matvec
   plus the loop in C by calling back into Python for dnaupd. That still has call overhead.

   Better: replicate the Fortran call. SciPy's wrapper signature is unknown. Let's look
   at typical arpack-ng dnaupd:

   subroutine dnaupd(ido, bmat, n, which, nev, tol, resid, ncv, v, ldv, iparam, ipntr,
                     workd, workl, lworkl, info)

   SciPy folds iparam/which/bmat into a dict and calls a custom wrapper, not the raw
   Fortran routine directly from the symbol ARNAUD_dnaupd (which is likely the raw one).

   We'll dlsym ARNAUD_dnaupd and call the raw Fortran routine. Need the exact ABI.
*/

typedef void (*dnaupd_fn)(
    int *ido, char *bmat, int *n, char *which, int *nev, double *tol,
    double *resid, int *ncv, double *v, int *ldv, int *iparam, int *ipntr,
    double *workd, double *workl, int *lworkl, int *info,
    /* hidden string lengths if gfortran */
    int bmat_len, int which_len
);

typedef void (*dneupd_fn)(
    int *rvec, char *howmny, int *select, double *dr, double *di,
    double *z, int *ldz, double *sigmar, double *sigmai, double *workev,
    char *bmat, int *n, char *which, int *nev, double *tol, double *resid,
    int *ncv, double *v, int *ldv, int *iparam, int *ipntr, double *workd,
    double *workl, int *lworkl, int *info,
    int howmny_len, int bmat_len, int which_len
);

static void csr_matvec(int n, const int *indptr, const int *indices, const double *data,
                       const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int start = indptr[i];
        int end = indptr[i + 1];
        for (int j = start; j < end; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

static PyObject *fast_eigs(PyObject *self, PyObject *args) {
    PyObject *lib_obj;
    PyArrayObject *indptr_a, *indices_a, *data_a, *v0_a;
    int k, ncv, maxiter;
    double tol;
    if (!PyArg_ParseTuple(args, "OOOOiiid", &lib_obj, &indptr_a, &indices_a, &data_a,
                          &v0_a, &k, &ncv, &maxiter, &tol)) {
        return NULL;
    }
    /* We don't use lib_obj; symbol resolved via dlsym of current process */
    void *handle = NULL;
    /* RTLD_DEFAULT */
    extern void *dlsym(void *, const char *);
    #define RTLD_DEFAULT ((void *) -2)
    dnaupd_fn dnaupd = (dnaupd_fn)dlsym(RTLD_DEFAULT, "ARNAUD_dnaupd");
    dneupd_fn dneupd = (dneupd_fn)dlsym(RTLD_DEFAULT, "ARNAUD_dneupd");
    if (!dnaupd || !dneupd) {
        PyErr_SetString(PyExc_RuntimeError, "could not dlsym ARNAUD_dnaupd/dneupd");
        return NULL;
    }

