    double *resid = (double *)malloc(sizeof(double) * n);
    double *v0 = (double *)PyArray_DATA(v0_a);
    memcpy(resid, v0, sizeof(double) * n);
    int ldv = n;
    double *v = (double *)calloc((size_t)n * ncv, sizeof(double));
    int iparam[11];
    memset(iparam, 0, sizeof(iparam));
    iparam[0] = 1;          /* ishift = 1 */
    iparam[2] = maxiter;    /* maxiter */
    iparam[3] = 1;          /* NB, blocksize */
    iparam[6] = 1;          /* mode = 1 */
    int ipntr[14];
    memset(ipntr, 0, sizeof(ipntr));
    double *workd = (double *)calloc(3 * (size_t)n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc(lworkl, sizeof(double));
    int info = 1; /* start from resid */

    int iter_guard = maxiter * (ncv + 5) + 1000;
    int steps = 0;
    while (steps < iter_guard) {
        dnaupd(&ido, bmat, &n, which, &nev, &tol, resid, &ncv, v, &ldv,
               iparam, ipntr, workd, workl, &lworkl, &info, 1, 2);
        steps++;
        if (ido == -1 || ido == 1) {
