            memcpy(workd + y0, workd + x0, sizeof(double) * n);
        } else if (ido == 99 || ido == 0) {
            break;
        } else {
            break;
        }
    }

    if (info != 0 && ido != 99) {
        /* still try extract if ido==99, else error */
    }

    int rvec = 1;
    char howmny[2] = {'A', 0};
    int *select = (int *)calloc(ncv, sizeof(int));
    double *dr = (double *)calloc(nev + 1, sizeof(double));
    double *di = (double *)calloc(nev + 1, sizeof(double));
    double *z = (double *)calloc((size_t)n * (nev + 1), sizeof(double));
    int ldz = n;
    double sigmar = 0.0, sigmai = 0.0;
    double *workev = (double *)calloc(3 * ncv, sizeof(double));
    int ierr = 0;
    dneupd(&rvec, howmny, select, dr, di, z, &ldz, &sigmar, &sigmai, workev,
           bmat, &n, which, &nev, &tol, resid, &ncv, v, &ldv, iparam, ipntr,
           workd, workl, &lworkl, &ierr, 1, 1, 2);

    int nconv = iparam[4];
    /* build complex eigenvalues and eigenvectors */
    npy_intp dims_w[1] = {k};
    npy_intp dims_v[2] = {n, k};
    PyArrayObject *w = (PyArrayObject *)PyArray_SimpleNew(1, dims_w, NPY_COMPLEX128);
    PyArrayObject *vecs = (PyArrayObject *)PyArray_SimpleNew(2, dims_v, NPY_COMPLEX128);
    double complex *wc = (double complex *)PyArray_DATA(w);
    double complex *vc = (double complex *)PyArray_DATA(vecs);
    /* zero */
    memset(wc, 0, sizeof(double complex) * k);
    memset(vc, 0, sizeof(double complex) * (size_t)n * k);

    /* dneupd packs conjugate pairs: if di[i] != 0, next is conjugate.
       z columns are real/imag parts. */
    int out = 0;
    for (int i = 0; i < nev && out < k; i++) {
        if (di[i] == 0.0) {
            wc[out] = dr[i];
            for (int r = 0; r < n; r++) {
                vc[r + out * n] = z[r + i * n];  /* wait, z may be column-major ld z */
            }
            /* z is column-major with ldz=n, so z[r + i*ldz] */
            out++;
        } else {
            /* pair i, i+1 */
            wc[out] = dr[i] + I * di[i];
            if (out + 1 < k) wc[out + 1] = dr[i] - I * di[i];
            for (int r = 0; r < n; r++) {
                double zr = z[r + i * n];
                double zi = z[r + (i + 1) * n];
                vc[r + out * n] = zr + I * zi;
                if (out + 1 < k) vc[r + (out + 1) * n] = zr - I * zi;
            }
            out += 2;
            i++; /* skip conjugate partner */
        }
    }

    free(resid); free(v); free(workd); free(workl); free(select);
    free(dr); free(di); free(z); free(workev);

    PyObject *ret = Py_BuildValue("NNi", w, vecs, nconv);
    return ret;
}

static PyMethodDef methods[] = {
    {"fast_eigs", fast_eigs, METH_VARARGS, "fast eigs"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastarpack", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastarpack(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
