            int y0 = ipntr[1] - 1;
            csr_matvec(n, indptr, indices, data, workd + x0, workd + y0);
        } else if (ido == 2) {
            int x0 = ipntr[0] - 1;
            int y0 = ipntr[1] - 1;
            memcpy(workd + y0, workd + x0, sizeof(double) * (size_t)n);
        } else {
            break;
        }
    }

    int rvec = 1;
    char howmny[1] = {'A'};
    int *select = (int *)calloc((size_t)ncv, sizeof(int));
    double *dr = (double *)calloc((size_t)nev + 1, sizeof(double));
    double *di = (double *)calloc((size_t)nev + 1, sizeof(double));
    double *z = (double *)calloc((size_t)n * (nev + 1), sizeof(double));
    int ldz = n;
    double sigmar = 0.0, sigmai = 0.0;
    double *workev = (double *)calloc(3 * (size_t)ncv, sizeof(double));
    int ierr = 0;
    dneupd(&rvec, howmny, select, dr, di, z, &ldz, &sigmar, &sigmai, workev,
           bmat, &n, which, &nev, &tol, resid, &ncv, v, &ldv, iparam, ipntr,
           workd, workl, &lworkl, &ierr, 1, 1, 2);

    int nconv = iparam[4];

    npy_intp dims_w[1] = {k};
    npy_intp dims_v[2] = {n, k};
    PyObject *w = PyArray_SimpleNew(1, dims_w, NPY_COMPLEX128);
    PyObject *vecs = PyArray_SimpleNew(2, dims_v, NPY_COMPLEX128);
    double complex *wc = (double complex *)PyArray_DATA((PyArrayObject *)w);
    double complex *vc = (double complex *)PyArray_DATA((PyArrayObject *)vecs);
    memset(wc, 0, sizeof(double complex) * (size_t)k);
    memset(vc, 0, sizeof(double complex) * (size_t)n * (size_t)k);

    int out = 0;
    for (int i = 0; i < nev && out < k; i++) {
        if (di[i] == 0.0) {
            wc[out] = dr[i] + 0.0 * I;
            for (int r = 0; r < n; r++) {
                vc[(npy_intp)r + (npy_intp)out * n] = z[r + i * ldz] + 0.0 * I;
            }
            out++;
