                }
            }
            out += 2;
            i++;
        }
    }

    free(resid); free(v); free(workd); free(workl); free(select);
    free(dr); free(di); free(z); free(workev);

    return Py_BuildValue("NNiii", w, vecs, nconv, info, ierr);
}

