        return NULL;
    }

    int n = (int)PyArray_DIM((PyArrayObject *)indptr_a, 0) - 1;
    int *indptr = (int *)PyArray_DATA((PyArrayObject *)indptr_a);
    int *indices = (int *)PyArray_DATA((PyArrayObject *)indices_a);
    double *data = (double *)PyArray_DATA((PyArrayObject *)data_a);
    double *v0 = (double *)PyArray_DATA((PyArrayObject *)v0_a);

    ArnaudState st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = 0;       /* LM */
    st.ido = 0;
    st.info = 1;        /* use supplied resid */
    st.bmat = 0;        /* 'I' */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    double *resid = (double *)malloc(sizeof(double) * (size_t)n);
    memcpy(resid, v0, sizeof(double) * (size_t)n);
    double *v = (double *)calloc((size_t)n * (size_t)ncv, sizeof(double));
    int *ipntr = (int *)calloc(14, sizeof(int));
    double *workd = (double *)calloc(3 * (size_t)n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc((size_t)lworkl, sizeof(double));

    int guard = maxiter * (ncv + 10) + 1000;
    int steps = 0;
    while (steps < guard) {
        dnaupd(&st, resid, v, ipntr, workd, workl);
        steps++;
        int ido = st.ido;
        if (ido == 1 || ido == 5 || ido == -1) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            /* scipy's wrapper uses 0-based slices: workd[ipntr[0]:ipntr[0]+n] */
            if (x0 < 0 || y0 < 0 || x0 + n > 3 * n || y0 + n > 3 * n) {
                /* try 1-based */
                x0 = ipntr[0] - 1;
                y0 = ipntr[1] - 1;
            }
            csr_matvec(n, indptr, indices, data, workd + x0, workd + y0);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, sizeof(double) * (size_t)n);
        } else {
            break;
        }
