                                  "info", st.info,
                                  "nconv", st.nconv,
                                  "ido", st.ido,
                                  "steps", steps,
                                  "rnorm2", rnorm,
                                  "iter", st.iter);
    free(resid); free(v); free(ipntr); free(workd); free(workl);
    return ret;
}

