#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int start = indptr[i];
        int end = indptr[i + 1];
        for (int j = start; j < end; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

/* fast_eigs(wrap, state_dict, resid, v, ipntr, workd, workl, indptr, indices, data)
   wrap is the bound? No, dnaupd_wrap is a module-level function expecting
   (state, resid, v, ipntr, workd, workl). We call it via PyObject_CallFunctionObjArgs.
*/
static PyObject *fast_eigs(PyObject *self, PyObject *args) {
    PyObject *wrap, *state;
    PyArrayObject *resid, *v, *ipntr, *workd, *workl;
    PyArrayObject *indptr_a, *indices_a, *data_a;
    if (!PyArg_ParseTuple(args, "OOOOOOOOO", &wrap, &state, &resid, &v, &ipntr,
                          &workd, &workl, &indptr_a, &indices_a, &data_a)) {
        return NULL;
    }

    int n = (int)PyArray_DIM(indptr_a, 0) - 1;
    const int *indptr = (const int *)PyArray_DATA(indptr_a);
    const int *indices = (const int *)PyArray_DATA(indices_a);
    const double *data = (const double *)PyArray_DATA(data_a);
    double *wd = (double *)PyArray_DATA(workd);
    int *ip = (int *)PyArray_DATA(ipntr);

    int steps = 0;
    int guard = 5000000;
    while (steps < guard) {
        PyObject *ret = PyObject_CallFunctionObjArgs(
            wrap, state, (PyObject *)resid, (PyObject *)v, (PyObject *)ipntr,
            (PyObject *)workd, (PyObject *)workl, NULL);
        if (ret == NULL) {
            return NULL;
        }
        Py_DECREF(ret);
        steps++;

        PyObject *ido_obj = PyDict_GetItemString(state, "ido"); /* borrowed */
        if (ido_obj == NULL) {
            PyErr_SetString(PyExc_RuntimeError, "missing ido");
            return NULL;
        }
        long ido = PyLong_AsLong(ido_obj);
        if (ido == 1 || ido == 5 || ido == -1) {
            int x0 = ip[0];
            int y0 = ip[1];
            csr_matvec(n, indptr, indices, data, wd + x0, wd + y0);
        } else if (ido == 2) {
            int x0 = ip[0];
            int y0 = ip[1];
            memcpy(wd + y0, wd + x0, sizeof(double) * (size_t)n);
        } else if (ido == 4) {
            /* shouldn't happen with info=1, but fill resid with ones */
            double *r = (double *)PyArray_DATA(resid);
            for (int i = 0; i < n; i++) r[i] = 1.0;
        } else {
            break;
        }
    }

    PyObject *info_obj = PyDict_GetItemString(state, "info");
    long info = info_obj ? PyLong_AsLong(info_obj) : -999;
    return Py_BuildValue("il", steps, info);
}

static PyMethodDef methods[] = {
    {"fast_eigs", fast_eigs, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastarpack", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_fastarpack(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
