                          int *ipntr, double *workd, double *workl, int n);

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int start = indptr[i];
        int end = indptr[i + 1];
        for (int j = start; j < end; j++) s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

