/*
 * fast_loop(wrap, state, resid, v, ipntr, workd, workl, indptr, indices, data, n)
 * wrap is dnaupd_wrap. ido is read from the dict each iteration (unavoidable if we
 * use the wrap), BUT we cache the dict key object... PyDict_GetItemString still
 * hashes. We'll intern the key once and use PyDict_GetItem.
 *
 * Also cache pointers to the numpy data buffers.
 */
static PyObject *fast_loop(PyObject *self, PyObject *args) {
    PyObject *wrap, *state;
    PyArrayObject *resid, *v, *ipntr, *workd, *workl, *indptr_a, *indices_a, *data_a;
    int n;
    if (!PyArg_ParseTuple(args, "OOOOOOOOOOi", &wrap, &state,
                          &resid, &v, &ipntr, &workd, &workl,
                          &indptr_a, &indices_a, &data_a, &n)) {
        return NULL;
    }

    const int *indptr = (const int *)PyArray_DATA(indptr_a);
    const int *indices = (const int *)PyArray_DATA(indices_a);
    const double *data = (const double *)PyArray_DATA(data_a);
    double *wd = (double *)PyArray_DATA(workd);
    int *ip = (int *)PyArray_DATA(ipntr);

    PyObject *ido_key = PyUnicode_InternFromString("ido");
    PyObject *info_key = PyUnicode_InternFromString("info");
    if (!ido_key || !info_key) return NULL;

    int steps = 0;
    const int guard = 10000000;
    while (steps < guard) {
        PyObject *ret = PyObject_CallFunctionObjArgs(
            wrap, state, (PyObject *)resid, (PyObject *)v, (PyObject *)ipntr,
            (PyObject *)workd, (PyObject *)workl, NULL);
        if (ret == NULL) {
            Py_DECREF(ido_key); Py_DECREF(info_key);
            return NULL;
        }
        Py_DECREF(ret);
        steps++;

        PyObject *ido_obj = PyDict_GetItem(state, ido_key);
        long ido = PyLong_AsLong(ido_obj);
        if (ido == 1 || ido == 5) {
            int x0 = ip[0];
            int y0 = ip[1];
            csr_matvec(n, indptr, indices, data, wd + x0, wd + y0);
        } else if (ido == -1) {
            int x0 = ip[0];
            int y0 = ip[1];
            csr_matvec(n, indptr, indices, data, wd + x0, wd + y0);
        } else if (ido == 2) {
            memcpy(wd + ip[1], wd + ip[0], sizeof(double) * (size_t)n);
        } else if (ido == 4) {
            double *r = (double *)PyArray_DATA(resid);
            for (int i = 0; i < n; i++) r[i] = 1.0;
        } else {
            break;
        }
    }
    PyObject *info_obj = PyDict_GetItem(state, info_key);
    long info = info_obj ? PyLong_AsLong(info_obj) : -1;
    Py_DECREF(ido_key); Py_DECREF(info_key);
    return Py_BuildValue("il", steps, info);
}

