/* Persistent workspace, reused across problems of the same n. */
static int cap_n = 0, cap_ncv = 0;
static double *g_resid = NULL, *g_v = NULL, *g_workd = NULL, *g_workl = NULL;
static int *g_ipntr = NULL;

static void ensure(int n, int ncv) {
    if (n <= cap_n && ncv <= cap_ncv && g_resid) return;
    free(g_resid); free(g_v); free(g_workd); free(g_workl); free(g_ipntr);
    cap_n = n; cap_ncv = ncv;
    g_resid = (double *)malloc(sizeof(double) * (size_t)n);
    g_v = (double *)malloc(sizeof(double) * (size_t)n * ncv);
    g_workd = (double *)malloc(sizeof(double) * 3 * (size_t)n);
    g_workl = (double *)malloc(sizeof(double) * 3 * ncv * (ncv + 2));
    g_ipntr = (int *)malloc(sizeof(int) * 14);
