    memset(g_v, 0, sizeof(double) * (size_t)n * ncv);
    memset(g_workd, 0, sizeof(double) * 3 * (size_t)n);
    memset(g_workl, 0, sizeof(double) * 3 * ncv * (ncv + 2));
    memset(g_ipntr, 0, sizeof(int) * 14);

